export interface DurationObservation {
  duration: number
  recordedAt: number
}

export function smoothDuration(observations: DurationObservation[], smoothing: 'latest' | 'average' | 'p95' | 'median'): number {
  if (!observations.length) { return 0 }
  if (smoothing === 'latest') { return observations.reduce((latest, item) => item.recordedAt > latest.recordedAt ? item : latest).duration }
  const values = observations.map(item => item.duration).sort((a, b) => a - b)
  if (smoothing === 'average') { return Math.round(values.reduce((sum, value) => sum + value, 0) / values.length) }
  if (smoothing === 'p95') { return values[Math.ceil(values.length * 0.95) - 1] }
  const middle = Math.floor(values.length / 2)
  return values.length % 2 ? values[middle] : Math.floor((values[middle - 1] + values[middle]) / 2)
}
import type { DurationObservation } from './duration-smoothing'
import { promises as fs } from 'node:fs'
import { dirname, resolve } from 'pathe'
import { smoothDuration } from './duration-smoothing'

export type DurationHistory = Record<string, DurationObservation[]>

function observations(value: unknown): DurationObservation[] {
  if (typeof value === 'number' && Number.isFinite(value)) { return [{ duration: value, recordedAt: 0 }] }
  if (!value || typeof value !== 'object') { return [] }
  const source = 'observations' in value ? (value as any).observations : [value]
  if (!Array.isArray(source)) { return [] }
  return source.filter((item): item is DurationObservation => item && typeof item.duration === 'number' && Number.isFinite(item.duration) && typeof item.recordedAt === 'number' && Number.isFinite(item.recordedAt))
}

export async function readDurationHistory(root: string, path: string, ttl: number): Promise<DurationHistory | null> {
  try {
    const raw = JSON.parse(await fs.readFile(resolve(root, path), 'utf8'))
    if (!raw || typeof raw !== 'object' || Array.isArray(raw)) { return null }
    const oldest = Date.now() - ttl
    return Object.fromEntries(Object.entries(raw).map(([file, value]) => [file, observations(value).filter(item => !ttl || item.recordedAt === 0 || item.recordedAt >= oldest)]))
  }
  catch { return null }
}

export function getDuration(history: DurationHistory, path: string, ttl: number, smoothing: 'latest' | 'average' | 'p95' | 'median'): number {
  const oldest = Date.now() - ttl
  return smoothDuration((history[path] || []).filter(item => !ttl || item.recordedAt === 0 || item.recordedAt >= oldest), smoothing)
}

export async function writeDurationHistory(root: string, path: string, updates: Record<string, number>, maxRuns: number): Promise<void> {
  const history = await readDurationHistory(root, path, 0) || {}
  const now = Date.now()
  for (const [file, duration] of Object.entries(updates)) { history[file] = [...(history[file] || []), { duration: Math.round(duration), recordedAt: now }].sort((a, b) => b.recordedAt - a.recordedAt).slice(0, maxRuns) }
  const output = Object.fromEntries(Object.entries(history).map(([file, items]) => [file, maxRuns === 1 ? items[0] : { observations: items }]))
  const target = resolve(root, path)
  await fs.mkdir(dirname(target), { recursive: true })
  await fs.writeFile(target, `${JSON.stringify(output, null, 2)}\n`)
}

